/** Offers `data` as a file download without navigating. The temporary object URL is revoked once the browser has taken the file. */
export function downloadFile(name: string, data: BlobPart, type: string): void {
  const url = URL.createObjectURL(new Blob([data], { type }));
  const link = Object.assign(document.createElement('a'), { href: url, download: name });
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/** A file name for a document title: lower case words joined by hyphens, with the extension of its type. */
export function fileNameFor(title: string, extension: string): string {
  const base = title.toLowerCase().replace(/\.[a-z0-9]{1,8}$/, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'document';
  return `${base}.${extension}`;
}

'use client';

import { useMemo, useState, useSyncExternalStore } from 'react';
import type { ReactNode } from 'react';
import { CodeXmlIcon, EyeIcon, RotateCcwIcon, SaveIcon, SearchCheckIcon } from 'lucide-react';
import { HtmlViewer } from '@hachej/boring-ui-kit/html-viewer';
import type { HtmlController } from '@hachej/boring-ui-kit/html';
import { Button } from '@/components/ui/button';
import { editorControls } from '../button/editor-controls';
import { downloadFile, fileNameFor } from './download';
import { copyText } from '../utils/utils';
import { InteractiveFrame } from './interactive-html';
import type { InteractiveHtml } from './interactive-html';
import { ViewerFrame, ViewerToggle } from './viewer-frame';
import type { ViewerShare, ViewerStatus } from './viewer-frame';
import { defaultViewerLabels, useViewerText } from './viewer-window';
import type { ViewerLabels } from './viewer-window';

export type HtmlPaneMode = 'preview' | 'source';

export interface HtmlPaneProps {
  /** Borrowed: the host owns the controller and disposes it. */
  readonly controller: HtmlController;
  readonly title?: string;
  readonly subtitle?: ReactNode;
  readonly target?: unknown;
  readonly revision?: string;
  readonly initialMode?: HtmlPaneMode;
  /** Reports the person's choice, so a host that remounts the pane (for a new revision) can start it in the same mode. */
  readonly onModeChange?: (mode: HtmlPaneMode) => void;
  /**
   * Host opt-in (off by default): the preview then runs the page's own scripts in a sandboxed frame with an opaque origin and a
   * Content-Security-Policy limited to inline code and `scriptSources`. See registry/README.md. Without it the preview is the passive,
   * script-free rendering of `@hachej/boring-ui-kit/html-viewer`.
   */
  readonly interactive?: InteractiveHtml;
  /** Leading header content, before the title. */
  readonly headerStart?: ReactNode;
  readonly controls?: ReactNode;
  readonly onRefresh?: () => unknown;
  readonly onShare?: ViewerShare;
  readonly onOpenInNewTab?: () => unknown;
  readonly onClose?: () => unknown;
  readonly testId?: string;
  /** Overrides the title's `data-testid` (default `<testId>-title`). */
  readonly titleTestId?: string;
  readonly className?: string;
  /** The pane's and its bar's words, over the window's and `defaultViewerLabels`. */
  readonly labels?: Partial<ViewerLabels> | undefined;
}

export function htmlStatus(state: ReturnType<HtmlController['getSnapshot']>, labels: ViewerLabels = defaultViewerLabels): ViewerStatus {
  if (state.lifecycle === 'disposed') return { label: labels.closed };
  if (state.save.kind === 'pending') return { label: labels.saving };
  if (state.save.kind === 'settled' && state.save.result.kind === 'unknown') return { label: labels.saveUnconfirmed, tone: 'warning' };
  if (state.remote !== null || state.save.kind === 'settled' && state.save.result.kind === 'conflict') return { label: labels.changedElsewhere, tone: 'warning' };
  if (state.readOnly) return { label: labels.readOnly, kind: 'read-only' };
  return state.dirty ? { label: labels.unsaved, tone: 'warning' } : { label: labels.saved, tone: 'success', kind: 'saved' };
}

/** The HTML safe preview and source editor in the standard viewer frame. The preview never runs scripts; a host-enabled interactive preview runs them, in a sandbox. */
export function HtmlPane({ controller, labels: ownLabels, title = 'HTML document', subtitle, target, revision, initialMode = 'preview', onModeChange, interactive, headerStart, controls, onRefresh, onShare, onOpenInNewTab, onClose, testId = 'viewer', titleTestId, className }: HtmlPaneProps) {
  const state = useSyncExternalStore(controller.subscribe, controller.getSnapshot, controller.getSnapshot);
  const { labels } = useViewerText(ownLabels);
  const [mode, setModeState] = useState<HtmlPaneMode>(initialMode);
  const setMode = (next: HtmlPaneMode) => { setModeState(next); onModeChange?.(next); };
  const [reload, setReload] = useState(0);
  const [error, setError] = useState<string>();
  const pending = state.save.kind === 'pending';
  const unconfirmed = state.save.kind === 'settled' && state.save.result.kind === 'unknown';
  const disposed = state.lifecycle === 'disposed';
  const perform = (action: () => Promise<{ readonly kind: string; readonly reason?: string }>) => {
    setError(undefined);
    void Promise.resolve().then(action).then(result => { if ((result.kind === 'denied' || result.kind === 'unavailable' || result.kind === 'file_too_large') && result.reason) setError(result.reason); })
      .catch(() => setError(labels.operationFailed));
  };
  const filename = useMemo(() => fileNameFor(title, 'html'), [title]);
  return <ViewerFrame title={title} subtitle={subtitle} headerStart={headerStart} status={htmlStatus(state, labels)} labels={labels} target={target} revision={revision} testId={testId} {...(titleTestId ? { titleTestId } : {})} className={className}
    onRefresh={() => { if (interactive && mode === 'preview') setReload(count => count + 1); return (onRefresh ?? (() => controller.actions.refresh()))(); }} onShare={onShare} onCopy={() => copyText(controller.getSnapshot().text)}
    onDownload={() => downloadFile(filename, controller.getSnapshot().text, 'text/html;charset=utf-8')} onOpenInNewTab={onOpenInNewTab} onClose={onClose}
    controls={<>
      <ViewerToggle label={labels.view} value={mode} onChange={setMode} options={[
        { id: 'preview', label: labels.htmlPreview, text: labels.preview, icon: <EyeIcon data-icon="inline-start" aria-hidden="true" />, testId: `${testId}-mode-preview` },
        { id: 'source', label: labels.htmlSource, text: labels.source, icon: <CodeXmlIcon data-icon="inline-start" aria-hidden="true" />, testId: `${testId}-mode-source` }]} />
      {!state.readOnly && state.dirty && <Button variant="ghost" size="icon-sm" aria-label={labels.save} title={labels.save} data-testid={`${testId}-save`} disabled={disposed || pending || unconfirmed} onClick={() => perform(() => controller.flush(controller.actions.selection()))}><SaveIcon data-icon="inline-start" aria-hidden="true" /></Button>}
      {unconfirmed && <Button variant="ghost" size="icon-sm" aria-label={labels.checkSave} title={labels.checkSave} onClick={() => perform(controller.actions.reconcile)}><SearchCheckIcon data-icon="inline-start" aria-hidden="true" /></Button>}
      {unconfirmed && <Button variant="ghost" size="icon-sm" aria-label={labels.abandon} title={labels.abandon} onClick={() => perform(controller.actions.abandon)}><RotateCcwIcon data-icon="inline-start" aria-hidden="true" /></Button>}
      {state.remote !== null && <Button variant="ghost" size="icon-sm" aria-label={labels.discardLocal} title={labels.discardLocal} disabled={pending || unconfirmed} onClick={() => perform(controller.actions.discardToRemote)}><RotateCcwIcon data-icon="inline-start" aria-hidden="true" /></Button>}
      {controls}
    </>}>
    {error && <p role="alert" className="m-0 px-3 py-2">{error}</p>}
    {interactive && mode === 'preview'
      ? <InteractiveFrame text={state.text} sources={interactive.scriptSources} reload={reload} title={`${title} (running)`} testId={testId} />
      : <HtmlViewer components={editorControls} controller={controller} title={title} header={false} mode={mode === 'source' ? 'source' : 'preview'} onModeChange={next => setMode(next)} className="boring-html-pane" />}
  </ViewerFrame>;
}

'use client';

import { useEffect, useMemo, useRef, useState } from 'react';
import type { PointerEvent, ReactNode } from 'react';
import { MaximizeIcon, ScanIcon, ZoomInIcon, ZoomOutIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { downloadFile } from './download';
import { formatBytes, useMediaUrl } from './media';
import type { MediaSource } from './media';
import { cn } from '../utils/utils';
import { useViewerBar, ViewerFrame } from './viewer-frame';
import type { ViewerShare, ViewerStatus } from './viewer-frame';
import { useViewerText } from './viewer-window';

export const IMAGE_TYPES: Readonly<Record<string, string>> = { 'image/png': 'PNG', 'image/jpeg': 'JPEG', 'image/gif': 'GIF', 'image/webp': 'WebP', 'image/svg+xml': 'SVG' };
const STEPS = [0.1, 0.25, 0.5, 0.75, 1, 1.5, 2, 3, 4, 6, 8];

export interface ImagePaneProps extends MediaSource {
  readonly name: string;
  readonly mediaType: string;
  readonly subtitle?: ReactNode;
  readonly status?: ViewerStatus;
  readonly target?: unknown;
  readonly revision?: string;
  /** Leading header content, before the title. */
  readonly headerStart?: ReactNode;
  readonly controls?: ReactNode;
  /** Re-reads the file; the host passes the new bytes, blob or URL back in. */
  readonly onRefresh?: () => unknown;
  readonly onShare?: ViewerShare;
  readonly onOpenInNewTab?: () => unknown;
  readonly onClose?: () => unknown;
  readonly testId?: string;
  /** Overrides the title's `data-testid` (default `<testId>-title`). */
  readonly titleTestId?: string;
  readonly className?: string;
}

/** Zoom steps and the level; on a narrow bar only the steps stay (the stage also zooms with + - 0). Fit and Actual size are in the "…" menu. */
export function ZoomControls({ testId, percent, ready, onStep, onFit }: { readonly testId: string; readonly percent: string; readonly ready: boolean; readonly onStep: (direction: 1 | -1) => void; readonly onFit: () => void }) {
  const { tight } = useViewerBar();
  const { labels } = useViewerText();
  return <div role="group" aria-label={labels.zoom} className="flex items-center gap-0.5">
    <Button variant="ghost" size="icon-sm" aria-label={labels.zoomOut} title={labels.zoomOut} data-testid={`${testId}-zoom-out`} disabled={!ready} onClick={() => onStep(-1)}><ZoomOutIcon data-icon="inline-start" aria-hidden="true" /></Button>
    {!tight && <Button variant="ghost" size="sm" data-testid={`${testId}-zoom-level`} aria-label={labels.zoomLevel(percent)} title={labels.fitToView} disabled={!ready} className="min-w-10" onClick={onFit}>{percent}</Button>}
    <Button variant="ghost" size="icon-sm" aria-label={labels.zoomIn} title={labels.zoomIn} data-testid={`${testId}-zoom-in`} disabled={!ready} onClick={() => onStep(1)}><ZoomInIcon data-icon="inline-start" aria-hidden="true" /></Button>
  </div>;
}

type Zoom = { readonly kind: 'fit' } | { readonly kind: 'scale'; readonly value: number };

/**
 * A read-only image viewer in the standard frame: fit to view by default, zoom, actual size, drag to pan when zoomed, a checkerboard
 * behind transparency. Every type, SVG included, is shown through an `<img>` from an object URL, never as markup.
 */
export function ImagePane({ name, mediaType, bytes, blob, url: hostUrl, subtitle, status, target, revision, headerStart, controls, onRefresh, onShare, onOpenInNewTab, onClose, testId = 'viewer', titleTestId, className }: ImagePaneProps) {
  const source = useMemo<MediaSource>(() => ({ ...(bytes ? { bytes } : {}), ...(blob ? { blob } : {}), ...(hostUrl ? { url: hostUrl } : {}) }), [bytes, blob, hostUrl]);
  const { url, size, blob: made } = useMediaUrl(source, mediaType);
  const supported = mediaType in IMAGE_TYPES;
  const { labels } = useViewerText();
  const [zoom, setZoom] = useState<Zoom>({ kind: 'fit' });
  const [natural, setNatural] = useState<{ width: number; height: number } | undefined>(undefined);
  const [failed, setFailed] = useState(false);
  const [fitScale, setFitScale] = useState(1);
  const stage = useRef<HTMLDivElement>(null);
  const image = useRef<HTMLImageElement>(null);
  const drag = useRef<{ x: number; y: number; left: number; top: number } | undefined>(undefined);
  useEffect(() => { setNatural(undefined); setFailed(false); }, [url]);
  const measure = () => {
    const box = stage.current, img = image.current;
    if (box && img && img.naturalWidth) setFitScale(Math.min(1, (box.clientWidth - 32) / img.naturalWidth, (box.clientHeight - 32) / img.naturalHeight));
  };
  useEffect(() => {
    const box = stage.current;
    if (!box || typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(measure);
    observer.observe(box);
    return () => observer.disconnect();
  }, [url]);
  const current = zoom.kind === 'fit' ? fitScale : zoom.value;
  const step = (direction: 1 | -1) => {
    const now = Number(current.toFixed(3));
    const next = direction > 0 ? STEPS.find(value => value > now + 0.001) : [...STEPS].reverse().find(value => value < now - 0.001);
    if (next) setZoom({ kind: 'scale', value: next });
  };
  const label = IMAGE_TYPES[mediaType] ?? mediaType;
  const facts = [label, natural && `${natural.width} × ${natural.height}`, size !== undefined && formatBytes(size)].filter(Boolean) as string[];
  const panning = zoom.kind === 'scale' && natural !== undefined && (natural.width * zoom.value > (stage.current?.clientWidth ?? 0) || natural.height * zoom.value > (stage.current?.clientHeight ?? 0));
  const begin = (event: PointerEvent<HTMLDivElement>) => {
    const box = stage.current;
    if (!panning || !box || event.button !== 0) return;
    drag.current = { x: event.clientX, y: event.clientY, left: box.scrollLeft, top: box.scrollTop };
    box.setPointerCapture?.(event.pointerId);
  };
  const move = (event: PointerEvent<HTMLDivElement>) => {
    const box = stage.current, start = drag.current;
    if (!box || !start) return;
    box.scrollLeft = start.left - (event.clientX - start.x);
    box.scrollTop = start.top - (event.clientY - start.y);
  };
  const end = () => { drag.current = undefined; };
  const downloadName = name.split('/').pop() || 'image';
  const download = () => { const data = made; if (data) downloadFile(downloadName, data, mediaType); else if (url) { const link = Object.assign(document.createElement('a'), { href: url, download: downloadName }); document.body.append(link); link.click(); link.remove(); } };
  const percent = `${Math.round(current * 100)}%`;
  return <ViewerFrame title={name.split('/').pop() || name} subtitle={<>{subtitle}{subtitle && facts.length > 0 && <span aria-hidden="true">·</span>}{facts.join(' · ')}</>} status={status} target={target} revision={revision} headerStart={headerStart} testId={testId} {...(titleTestId ? { titleTestId } : {})} className={className}
    onRefresh={onRefresh} onShare={onShare} onDownload={url ? download : undefined} onOpenInNewTab={onOpenInNewTab ?? (url ? () => { window.open(url, '_blank', 'noopener,noreferrer'); } : undefined)} onClose={onClose}
    menu={[
      { id: 'zoom-fit', label: labels.fitToView, icon: <ScanIcon className="size-4" />, disabled: !natural, onSelect: () => setZoom({ kind: 'fit' }) },
      { id: 'zoom-actual', label: labels.actualSize, icon: <MaximizeIcon className="size-4" />, disabled: !natural, onSelect: () => setZoom({ kind: 'scale', value: 1 }) }]}
    controls={<>
      <ZoomControls testId={testId} percent={percent} ready={Boolean(natural)} onStep={step} onFit={() => setZoom({ kind: 'fit' })} />
      {controls}
    </>}>
    <div ref={stage} data-testid={`${testId}-stage`} data-zoom={zoom.kind === 'fit' ? 'fit' : String(zoom.value)} data-panning={panning || undefined}
      onPointerDown={begin} onPointerMove={move} onPointerUp={end} onPointerCancel={end}
      className={cn('boring-viewer-stage relative min-h-0 flex-1 overflow-auto', panning && 'cursor-grab active:cursor-grabbing')} tabIndex={0} aria-label={labels.imageStage(name)}
      onKeyDown={event => { if (event.key === '+' || event.key === '=') step(1); else if (event.key === '-') step(-1); else if (event.key === '0') setZoom({ kind: 'fit' }); }}>
      {!supported ? <p role="alert" className="m-auto p-6 text-center text-sm text-muted-foreground">{labels.imageUnsupported(mediaType)}</p>
        : failed ? <p role="alert" className="m-auto p-6 text-center text-sm text-muted-foreground">{labels.imageUnreadable}</p>
        : url ? <div className="flex min-h-full min-w-full items-center justify-center p-4">
          <img ref={image} src={url} alt={name} data-testid={`${testId}-image`} draggable={false} decoding="async" referrerPolicy="no-referrer"
            onLoad={event => { setNatural({ width: event.currentTarget.naturalWidth, height: event.currentTarget.naturalHeight }); measure(); }} onError={() => setFailed(true)}
            style={natural ? { width: natural.width * current, height: natural.height * current, maxWidth: 'none' } : undefined}
            className="boring-viewer-checker block shrink-0 select-none  outline outline-1 outline-border" />
        </div> : <p role="status" className="m-auto p-6 text-sm text-muted-foreground">{labels.loading}</p>}
    </div>
  </ViewerFrame>;
}

'use client';

import type { ReactNode } from 'react';

/**
 * Host opt-in for running an HTML document's own scripts. `scriptSources` are the HTTPS origins the page may load libraries, styles and fonts
 * from (for example `https://cdnjs.cloudflare.com`). Everything else is closed: no network requests from the page, no frames, no forms.
 * Pinning library versions is the page's responsibility.
 */
export interface InteractiveHtml { readonly scriptSources: readonly string[] }

/** An origin only: `https://host` with an optional port, no path, no wildcard, nothing that could add a second CSP directive. */
const ORIGIN = /^https:\/\/[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*(:\d{1,5})?$/i;

export function allowedOrigins(sources: readonly string[]): string[] {
  return [...new Set(sources.map(source => source.trim().toLowerCase()).filter(source => ORIGIN.test(source)))];
}

/** The Content-Security-Policy the running page gets: inline script and style, the allow-listed origins for libraries, nothing else. */
export function interactivePolicy(sources: readonly string[]): string {
  const origins = allowedOrigins(sources).join(' ');
  const list = (...extra: string[]) => [...extra, ...(origins ? [origins] : [])].join(' ');
  return [
    "default-src 'none'",
    `script-src ${list("'unsafe-inline'")}`,
    `style-src ${list("'unsafe-inline'")}`,
    'img-src data: blob:',
    `font-src ${list('data:')}`,
    "connect-src 'none'",
    "frame-src 'none'",
    "base-uri 'none'",
    "form-action 'none'",
  ].join('; ');
}

/**
 * The document the frame loads: the policy and a no-referrer rule come first, so they apply before any of the page's own markup is parsed.
 * A second doctype or head in the page is ignored by the parser; a meta policy of the page's own can only tighten this one.
 */
export function interactiveDocument(text: string, sources: readonly string[]): string {
  return `<!doctype html><meta http-equiv="Content-Security-Policy" content="${interactivePolicy(sources).replaceAll('"', '&quot;')}"><meta name="referrer" content="no-referrer">${text}`;
}

/**
 * The page running in a sandboxed frame: `allow-scripts` only. There is no `allow-same-origin`, so the page has an opaque origin (no cookies,
 * storage or access to this page), and no top navigation, popups, forms, downloads or modals. `allow=""` withholds camera, microphone, location
 * and the other powerful features. Changing `reload` loads the page again from the start.
 */
export function InteractiveFrame({ text, sources, reload = 0, title = 'HTML page (running)', testId = 'viewer', children }: {
  readonly text: string;
  readonly sources: readonly string[];
  readonly reload?: number;
  readonly title?: string;
  readonly testId?: string;
  readonly children?: ReactNode;
}) {
  return <div className="boring-html-run flex min-h-0 flex-1 flex-col" data-testid={`${testId}-run`}>
    <iframe key={reload} title={title} sandbox="allow-scripts" allow="" referrerPolicy="no-referrer" srcDoc={interactiveDocument(text, sources)}
      data-testid={`${testId}-run-frame`} className="size-full min-h-0 flex-1" />
    {children}
  </div>;
}

'use client';

import { useCallback, useMemo, useRef, useState, useSyncExternalStore } from 'react';
import type { ReactNode } from 'react';
import { CodeXmlIcon, PencilLineIcon, SaveIcon } from 'lucide-react';
import { MarkdownEditor } from '@hachej/boring-ui-kit/markdown-editor';
import type { MarkdownEditorProps, MarkdownImageResolver, MarkdownMountedTools, MarkdownRichSafety } from '@hachej/boring-ui-kit/markdown-editor';
import type { MarkdownController } from '@hachej/boring-ui-kit/markdown';
import { Button } from '@/components/ui/button';
import { Toggle } from '@/components/ui/toggle';
import { editorControls } from '../button/editor-controls';
import { downloadFile, fileNameFor } from './download';
import { copyText } from '../utils/utils';
import { ViewerFrame, ViewerToggle } from './viewer-frame';
import type { ViewerShare, ViewerStatus } from './viewer-frame';
import { defaultViewerLabels, useViewerText, useViewerWindow } from './viewer-window';
import type { ViewerLabels } from './viewer-window';

export interface MarkdownPaneProps {
  /** Borrowed: the host owns the controller and disposes it. */
  readonly controller: MarkdownController;
  readonly title?: string;
  readonly subtitle?: ReactNode;
  readonly target?: unknown;
  readonly revision?: string;
  readonly initialMode?: 'rich' | 'source';
  /** Reports the person's choice, so a host that remounts the pane (for a new revision) can start it in the same mode. */
  readonly onModeChange?: (mode: 'rich' | 'source') => void;
  readonly placeholder?: string;
  /** Defaults to 1200ms idle autosave; false keeps the Save button. */
  readonly autosave?: MarkdownEditorProps['autosave'];
  /** Registers the flush for owner teardown; this is not a navigation guard. */
  readonly onAutosaveChange?: MarkdownEditorProps['onAutosaveChange'];
  /** Registers with a host navigation guard whose onClose handles refused saves and deliberate discard. */
  readonly onBeforeLeaveChange?: MarkdownEditorProps['onAutosaveChange'];
  /** Pinned by default on desktop. Phones always use the selection bubble. */
  readonly formattingToolbar?: MarkdownEditorProps['formattingToolbar'];
  /** Leading header content, before the title. */
  readonly headerStart?: ReactNode;
  /** Extra viewer controls, for example a version switcher. */
  readonly controls?: ReactNode;
  /** Defaults to the controller's refresh: a clean document follows the saved one, unsaved edits are kept and shown as changed elsewhere. */
  readonly onRefresh?: () => unknown;
  readonly onShare?: ViewerShare;
  readonly onOpenInNewTab?: () => unknown;
  readonly onClose?: () => unknown;
  /** Host mapping from an image address in the document to a loadable URL. Images stay inert without it. */
  readonly resolveImage?: MarkdownImageResolver;
  readonly onMountedTools?: (tools: MarkdownMountedTools | null) => void;
  readonly testId?: string;
  /** Overrides the title's `data-testid` (default `<testId>-title`). */
  readonly titleTestId?: string;
  readonly className?: string;
  /** The pane's and its bar's words, over the window's and `defaultViewerLabels`. */
  readonly labels?: Partial<ViewerLabels> | undefined;
}

/** The status chip for a Markdown controller: Saved, Unsaved, Saving, Changed elsewhere, Read-only. */
export function markdownStatus(state: ReturnType<MarkdownController['getSnapshot']>, labels: ViewerLabels = defaultViewerLabels): ViewerStatus {
  if (state.lifecycle === 'disposed') return { label: labels.closed };
  if (state.save.kind === 'pending') return { label: labels.saving };
  if (state.save.kind === 'settled' && state.save.result.kind === 'unknown') return { label: labels.saveUnconfirmed, tone: 'warning' };
  if (state.save.kind === 'settled' && state.save.result.kind === 'conflict' || state.remote !== null) return { label: labels.changedElsewhere, tone: 'warning' };
  if (state.readOnly) return { label: labels.readOnly, kind: 'read-only' };
  return state.dirty ? { label: labels.unsaved, tone: 'warning' } : { label: labels.saved, tone: 'success', kind: 'saved' };
}

/** The Markdown editor in the standard viewer frame: mode toggle, Save while there are edits, Share, and Reload, Copy and Download under the "…" menu. */
export function MarkdownPane({ controller, title: givenTitle, labels: ownLabels, subtitle, target, revision, initialMode = 'rich', onModeChange, placeholder, formattingToolbar = 'pinned', autosave: ownAutosave, onAutosaveChange, onBeforeLeaveChange, headerStart, controls, onRefresh, onShare, onOpenInNewTab, onClose, resolveImage, onMountedTools, testId = 'viewer', titleTestId, className }: MarkdownPaneProps) {
  const state = useSyncExternalStore(controller.subscribe, controller.getSnapshot, controller.getSnapshot);
  const { labels } = useViewerText(ownLabels);
  const window = useViewerWindow();
  const autosave = ownAutosave ?? window?.autosave ?? true;
  const flush = useRef<(() => Promise<boolean>) | null>(null);
  const registerAutosave = useCallback((save: (() => Promise<boolean>) | null) => { flush.current = save; onAutosaveChange?.(save); onBeforeLeaveChange?.(save); }, [onAutosaveChange, onBeforeLeaveChange]);
  const close = onClose ? async () => {
    if (autosave !== false && flush.current && !await flush.current() && !onBeforeLeaveChange) return false;
    return onClose();
  } : undefined;
  const title = givenTitle ?? labels.document;
  const [requested, setRequestedState] = useState<'rich' | 'source'>(initialMode);
  const setRequested = (next: 'rich' | 'source') => { setRequestedState(next); onModeChange?.(next); };
  const [toolbar, setToolbar] = useState(formattingToolbar);
  const [safety, setSafety] = useState<MarkdownRichSafety>({ safe: true });
  const mode = safety.safe ? requested : 'source';
  const unavailable = state.readOnly || state.lifecycle !== 'active';
  const pending = state.save.kind === 'pending';
  const unconfirmed = state.save.kind === 'settled' && state.save.result.kind === 'unknown';
  const [refused, setRefused] = useState<{ readonly save: typeof state.save; readonly label: string } | null>(null);
  const report: NonNullable<MarkdownEditorProps['onSaveResult']> = result => {
    if (result.kind === 'saved' || result.kind === 'conflict') setRefused(null);
    else if (result.kind === 'denied' || result.kind === 'unavailable' || result.kind === 'file_too_large') {
      const reason = result.reason ?? result.kind;
      setRefused({ save: controller.getSnapshot().save, label: labels.notSaved(reason.length > 48 ? `${reason.slice(0, 47)}…` : reason) });
    }
  };
  const save = () => {
    setRefused(null);
    void controller.flush(controller.actions.selection()).then(report, () => setRefused({ save: controller.getSnapshot().save, label: labels.notSaved(labels.saveFailedReason) }));
  };
  const filename = useMemo(() => fileNameFor(title, 'md'), [title]);
  return <ViewerFrame showSavedStatus title={title} subtitle={subtitle} headerStart={headerStart} status={refused && refused.save === state.save && state.save.kind !== 'pending' ? { label: refused.label, tone: 'warning' } : markdownStatus(state, labels)} target={target} labels={labels} revision={revision} testId={testId} {...(titleTestId ? { titleTestId } : {})} className={className}
    onRefresh={onRefresh ?? (() => controller.actions.refresh())} onShare={onShare} onCopy={() => copyText(controller.getSnapshot().text)}
    onDownload={() => downloadFile(filename, controller.getSnapshot().text, 'text/markdown;charset=utf-8')} onOpenInNewTab={onOpenInNewTab} onClose={close}
    controls={<>
      {mode === 'rich' && <Toggle size="sm" className="max-[640px]:hidden" aria-label="Pin formatting toolbar" title="Pin formatting toolbar" pressed={toolbar === 'pinned'}
        onPressedChange={pressed => setToolbar(pressed ? 'pinned' : 'selection')}>Aa</Toggle>}
      <ViewerToggle label={labels.editorMode} value={mode} onChange={setRequested} options={[
        { id: 'rich', label: labels.richText, text: labels.rich, icon: <PencilLineIcon data-icon="inline-start" aria-hidden="true" />, disabled: !safety.safe, testId: `${testId}-mode-rich` },
        { id: 'source', label: labels.markdownSource, text: labels.source, icon: <CodeXmlIcon data-icon="inline-start" aria-hidden="true" />, testId: `${testId}-mode-source` }]} />
      {autosave === false && !state.readOnly && state.dirty && <Button variant="ghost" size="icon-sm" aria-label={labels.save} title={labels.save} data-testid={`${testId}-save`} disabled={unavailable || pending || unconfirmed} onClick={save}><SaveIcon data-icon="inline-start" aria-hidden="true" /></Button>}
      {controls}
    </>}>
    <MarkdownEditor components={editorControls} controller={controller} title={title} header={false} autosave={autosave} onAutosaveChange={registerAutosave} onSaveResult={report} formattingToolbar={toolbar} mode={mode} onModeChange={setRequested} onRichSafety={setSafety}
      {...(placeholder === undefined ? {} : { placeholder })} {...(resolveImage ? { resolveImage } : {})} {...(onMountedTools ? { onMountedTools } : {})} className="boring-markdown-editor" />
  </ViewerFrame>;
}

import { useEffect, useMemo, useState } from 'react';

/** What a read-only media viewer shows: bytes or a Blob (the viewer owns the object URL it makes) or a URL the host owns. */
export interface MediaSource {
  readonly bytes?: Uint8Array | ArrayBuffer;
  readonly blob?: Blob;
  readonly url?: string;
}

/** A Blob for the source, or `undefined` when the host gave a URL (or nothing). */
export function mediaBlob(source: MediaSource, mediaType: string): Blob | undefined {
  if (source.blob) return source.blob;
  if (source.bytes) return new Blob([source.bytes as BlobPart], { type: mediaType });
  return undefined;
}

/** An object URL for the source, revoked when the source changes or the viewer unmounts. A host `url` is passed through untouched. */
export function useMediaUrl(source: MediaSource, mediaType: string): { url: string | undefined; size: number | undefined; blob: Blob | undefined } {
  const blob = useMemo(() => mediaBlob(source, mediaType), [source.blob, source.bytes, mediaType]); // eslint-disable-line react-hooks/exhaustive-deps
  const [made, setMade] = useState<string>();
  useEffect(() => {
    if (!blob) { setMade(undefined); return; }
    const url = URL.createObjectURL(blob);
    setMade(url);
    return () => { URL.revokeObjectURL(url); setMade(current => current === url ? undefined : current); };
  }, [blob]);
  return { url: blob ? made : source.url, size: blob?.size, blob };
}

export function formatBytes(size: number): string {
  if (size < 1024) return `${size} B`;
  if (size < 1024 * 1024) return `${(size / 1024).toFixed(size < 10240 ? 1 : 0)} KB`;
  return `${(size / 1024 / 1024).toFixed(1)} MB`;
}

