export interface PdfPaneProps extends MediaSource {
  readonly name: string;
  readonly subtitle?: ReactNode;
  readonly status?: ViewerStatus;
  readonly target?: unknown;
  readonly revision?: string;
  /** Leading header content, before the title. */
  readonly headerStart?: ReactNode;
  readonly controls?: ReactNode;
  readonly onRefresh?: () => unknown;
  readonly onShare?: ViewerShare;
  readonly onOpenInNewTab?: () => unknown;
  readonly onClose?: () => unknown;
  /** `false` draws the pages with pdf.js (for a host that knows its browser cannot render PDFs), `true` uses the browser's own viewer. Defaults to the browser's own report. */
  readonly inline?: boolean;
  /** How the browser's viewer opens the page: `width` (default) fits the page to the pane's width, `page` fits the whole page, `none` leaves the browser's own zoom. */
  readonly fit?: 'width' | 'page' | 'none';
  readonly testId?: string;
  /** Overrides the title's `data-testid` (default `<testId>-title`). */
  readonly titleTestId?: string;
  readonly className?: string;
}

/** The browser reports whether it has a built-in PDF viewer. Unknown (older browsers) is treated as yes: the frame is tried. */
export function browserShowsPdf(): boolean {
  const nav = globalThis.navigator as (Navigator & { pdfViewerEnabled?: boolean }) | undefined;
  return nav?.pdfViewerEnabled !== false;
}

const STEPS = [0.5, 0.75, 1, 1.25, 1.5, 2, 3, 4];

/**
 * A read-only PDF viewer in the standard frame, as in boring-ui v2: the browser's own PDF viewer in a frame over an object URL
 * (so its page navigation, zoom, search and print come with it). Where the browser cannot render PDFs inline (phones), pdf.js, loaded
 * only then, draws the pages with zoom and a page indicator; if that fails too (a damaged or password-protected file, no worker), a clear
 * message with Download and Open in new tab replaces it.
 */
export function PdfPane({ name, bytes, blob, url: hostUrl, subtitle, status, target, revision, headerStart, controls, onRefresh, onShare, onOpenInNewTab, onClose, inline, fit = 'width', testId = 'viewer', titleTestId, className }: PdfPaneProps) {
  const source = useMemo<MediaSource>(() => ({ ...(bytes ? { bytes } : {}), ...(blob ? { blob } : {}), ...(hostUrl ? { url: hostUrl } : {}) }), [bytes, blob, hostUrl]);
  const { url, size, blob: made } = useMediaUrl(source, 'application/pdf');
  const canShow = inline ?? browserShowsPdf();
  const { labels } = useViewerText();
  const downloadName = name.split('/').pop() || 'document.pdf';
  const download = () => { if (made) downloadFile(downloadName, made, 'application/pdf'); else if (url) { const link = Object.assign(document.createElement('a'), { href: url, download: downloadName }); document.body.append(link); link.click(); link.remove(); } };
  const open = onOpenInNewTab ?? (url ? () => { window.open(url, '_blank', 'noopener,noreferrer'); } : undefined);
  const [zoom, setZoom] = useState(1);
  const [pages, setPages] = useState<{ readonly count: number; readonly current: number }>();
  const [failed, setFailed] = useState(false);
  useEffect(() => { setPages(undefined); setFailed(false); }, [url]);
  const step = (direction: 1 | -1) => setZoom(now => (direction > 0 ? STEPS.find(value => value > now) : [...STEPS].reverse().find(value => value < now)) ?? now);
  const drawn = Boolean(url) && !canShow && !failed;
  return <ViewerFrame title={downloadName} subtitle={<>{subtitle}{subtitle && size !== undefined && <span aria-hidden="true">·</span>}{['PDF', size !== undefined && formatBytes(size)].filter(Boolean).join(' · ')}</>} status={status} target={target} revision={revision} headerStart={headerStart} testId={testId} {...(titleTestId ? { titleTestId } : {})} className={className}
    onRefresh={onRefresh} onShare={onShare} onDownload={url ? download : undefined} onOpenInNewTab={open} onClose={onClose}
    controls={drawn && pages ? <><ZoomControls testId={testId} percent={`${Math.round(zoom * 100)}%`} ready onStep={step} onFit={() => setZoom(1)} />{controls}</> : controls}>
    <div data-testid={`${testId}-stage`} data-pdf={url ? (canShow ? 'inline' : drawn ? 'pages' : 'fallback') : 'loading'} className="boring-viewer-stage relative flex min-h-0 flex-1">
      {!url ? <p role="status" className="m-auto p-6 text-sm text-muted-foreground">{labels.loading}</p>
        : canShow ? <iframe src={fit === 'none' ? url : `${url}#view=${fit === 'page' ? 'Fit' : 'FitH'}`} title={`${downloadName} (PDF)`} data-testid={`${testId}-frame-pdf`} className="size-full min-h-0 flex-1 bg-background" />
          : drawn ? <><PdfPages key={url} url={url} name={labels.pdfDocument(downloadName)} zoom={zoom} testId={testId} onLoad={count => setPages({ count, current: 1 })}
            onPage={current => setPages(now => now && now.current !== current ? { ...now, current } : now)} onError={() => setFailed(true)}
            onKey={key => { if (key === '+' || key === '=') step(1); else if (key === '-') step(-1); else if (key === '0') setZoom(1); }} />
            {pages && <Badge variant="secondary" data-testid={`${testId}-pdf-page-indicator`} aria-live="polite" className="pointer-events-none absolute bottom-3 left-1/2 -translate-x-1/2">{labels.pdfPage(pages.current, pages.count)}</Badge>}</>
          : <div role="alert" data-testid={`${testId}-pdf-fallback`} className="m-auto flex max-w-sm flex-col items-center gap-3 p-6 text-center">
            <span className="grid size-12 place-items-center  bg-muted text-muted-foreground"><FileTextIcon className="size-6" aria-hidden="true" /></span>
            <p className="m-0 text-sm font-medium">{labels.pdfUnsupported}</p>
            <p className="m-0 text-xs text-muted-foreground">{labels.pdfHint(downloadName, Boolean(open))}</p>
            <div className="flex flex-wrap justify-center gap-2">
              <Button variant="default" size="sm" data-testid={`${testId}-pdf-download`} onClick={download}><DownloadIcon data-icon="inline-start" aria-hidden="true" />{labels.download}</Button>
              {open && <Button variant="outline" size="sm" onClick={() => open()}>{labels.openInNewTab}</Button>}
            </div>
          </div>}
    </div>
  </ViewerFrame>;
}

'use client';

import { useEffect, useRef, useState } from 'react';
import type { PDFDocumentProxy, PDFWorker, RenderTask } from 'pdfjs-dist';
import { useViewerText } from './viewer-window';

/** Device pixels per CSS pixel are capped (3) and so is one page's canvas (about 8 megapixels) so a zoomed page stays within a phone's memory. */
const MAX_RATIO = 3;
const MAX_PIXELS = 8 * 1024 * 1024;

/**
 * pdf.js's own worker, from the package's worker entry. `new Worker(new URL(<package path>, import.meta.url))` is the form Vite and
 * webpack (Next) bundle as a worker; a host bundler that leaves the URL as is (esbuild) serves that path itself. Resolves once the
 * worker reports ready and rejects when it cannot load, so a missing worker shows the Download fallback instead of a spinner forever.
 */
function startWorker(signal: AbortSignal): Promise<Worker> {
  return new Promise((resolve, reject) => {
    const worker = new Worker(new URL('pdfjs-dist/build/pdf.worker.min.mjs', import.meta.url), { type: 'module' });
    const fail = () => { worker.terminate(); reject(new Error('The PDF worker could not start.')); };
    worker.addEventListener('message', () => { signal.removeEventListener('abort', fail); resolve(worker); }, { once: true });
    worker.addEventListener('error', fail, { once: true });
    signal.addEventListener('abort', fail, { once: true });
  });
}

/** Opens the document with pdf.js (loaded on demand) in its own worker. `close` destroys the document and stops the worker. */
async function openPdf(url: string, signal: AbortSignal): Promise<{ readonly document: PDFDocumentProxy; readonly close: () => void }> {
  const started = startWorker(signal);
  let worker: PDFWorker | undefined, task: { destroy(): Promise<void> } | undefined;
  const close = () => { void task?.destroy(); worker?.destroy(); void started.then(port => port.terminate(), () => {}); };
  try {
    const [pdfjs, port] = await Promise.all([import('pdfjs-dist'), started]);
    if (signal.aborted) throw signal.reason;
    worker = pdfjs.PDFWorker.create({ port });
    const loading = pdfjs.getDocument({ url, worker, verbosity: 0 });
    task = loading;
    const document = await loading.promise;
    if (signal.aborted) throw signal.reason;
    return { document, close };
  } catch (error) { close(); throw error; }
}

export interface PdfPagesProps {
  readonly url: string;
  readonly name: string;
  /** 1 fits the page to the pane's width. */
  readonly zoom: number;
  readonly testId: string;
  readonly onLoad: (pages: number) => void;
  readonly onPage: (page: number) => void;
  readonly onError: (error: unknown) => void;
  readonly onKey?: (key: string) => void;
}

/**
 * The pages of a PDF drawn by pdf.js, for a browser without a PDF viewer of its own (phones): stacked, fit to the pane's width times
 * `zoom`, rendered only near the viewport, crisp at the device's pixel ratio. Unmounting cancels rendering and destroys the document.
 */
export function PdfPages({ url, name, zoom, testId, onLoad, onPage, onError, onKey }: PdfPagesProps) {
  const { labels } = useViewerText();
  const scroller = useRef<HTMLDivElement>(null);
  const [document, setDocument] = useState<PDFDocumentProxy>();
  const [ratio, setRatio] = useState(Math.SQRT2);
  const [width, setWidth] = useState(0);
  const latest = useRef({ onLoad, onError });
  latest.current = { onLoad, onError };
  useEffect(() => {
    const abort = new AbortController();
    let close: (() => void) | undefined;
    openPdf(url, abort.signal).then(async opened => {
      close = opened.close;
      if (abort.signal.aborted) { close(); return; }
      const first = (await opened.document.getPage(1)).getViewport({ scale: 1 });
      if (abort.signal.aborted) return;
      setRatio(first.height / first.width);
      setDocument(opened.document);
      latest.current.onLoad(opened.document.numPages);
    }).catch(error => { if (!abort.signal.aborted) latest.current.onError(error); });
    return () => { abort.abort(); close?.(); };
  }, [url]);
  useEffect(() => {
    const box = scroller.current;
    if (!box) return;
    const measure = () => setWidth(Math.max(0, box.clientWidth - 16));
    measure();
    if (typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(measure);
    observer.observe(box);
    return () => observer.disconnect();
  }, []);
  const scrolled = () => {
    const box = scroller.current;
    if (!box) return;
    const line = box.scrollTop + box.clientHeight / 3;
    let page = 1;
    for (const element of box.querySelectorAll<HTMLElement>('[data-page]')) if (element.offsetTop <= line) page = Number(element.dataset.page);
    onPage(page);
  };
  const pageWidth = Math.floor(width * zoom);
  return <div ref={scroller} data-testid={`${testId}-pdf-pages`} aria-label={name} role="document" tabIndex={0} onScroll={scrolled}
    onKeyDown={event => onKey?.(event.key)} className="relative min-h-0 min-w-0 flex-1 overflow-auto p-2">
    {!document ? <p role="status" className="m-0 p-6 text-center text-sm text-muted-foreground">{labels.loading}</p>
      : <div className="flex w-max min-w-full flex-col items-center gap-2">
        {Array.from({ length: document.numPages }, (_, index) => <PdfPage key={index} document={document} number={index + 1} width={pageWidth} ratio={ratio} root={scroller.current} testId={testId} />)}
      </div>}
  </div>;
}

function PdfPage({ document, number, width, ratio, root, testId }: { readonly document: PDFDocumentProxy; readonly number: number; readonly width: number; readonly ratio: number; readonly root: Element | null; readonly testId: string }) {
  const box = useRef<HTMLDivElement>(null);
  const canvas = useRef<HTMLCanvasElement>(null);
  const [near, setNear] = useState(false);
  const [own, setOwn] = useState<number>();
  const [rendered, setRendered] = useState(false);
  useEffect(() => {
    const element = box.current;
    if (!element || typeof IntersectionObserver === 'undefined') { setNear(true); return; }
    const observer = new IntersectionObserver(entries => { if (entries.some(entry => entry.isIntersecting)) setNear(true); }, { root, rootMargin: '100% 0px' });
    observer.observe(element);
    return () => observer.disconnect();
  }, [root]);
  useEffect(() => {
    const element = canvas.current;
    if (!near || !width || !element) return;
    let cancelled = false, task: RenderTask | undefined;
    void document.getPage(number).then(page => {
      if (cancelled) return;
      const base = page.getViewport({ scale: 1 });
      setOwn(base.height / base.width);
      const viewport = page.getViewport({ scale: width / base.width });
      const scale = Math.min(globalThis.devicePixelRatio || 1, MAX_RATIO, Math.sqrt(MAX_PIXELS / (viewport.width * viewport.height)));
      element.width = Math.floor(viewport.width * scale);
      element.height = Math.floor(viewport.height * scale);
      task = page.render({ canvas: element, viewport, ...(scale === 1 ? {} : { transform: [scale, 0, 0, scale, 0, 0] }) });
      return task.promise.then(() => { if (!cancelled) setRendered(true); });
    }).catch(() => {});
    return () => { cancelled = true; task?.cancel(); };
  }, [document, number, width, near]);
  return <div ref={box} data-page={number} data-testid={`${testId}-pdf-page`} data-rendered={rendered || undefined} className="relative shrink-0 bg-background outline outline-1 outline-border"
    style={{ width, height: Math.round(width * (own ?? ratio)) }}>
    <canvas ref={canvas} data-testid={`${testId}-pdf-canvas`} className="absolute inset-0 size-full" />
  </div>;
}

import { copyText } from '../utils/utils';

/** What the frame hands the host when the person presses Share. `target` and `revision` are the host's own identifiers for what is shown. */
export interface ViewerShareRequest {
  readonly title: string;
  readonly target: unknown;
  readonly revision: string | undefined;
}

/** `shared`: the system share sheet took it. `copied`: a link is on the clipboard (the frame says so). Nothing: the host confirmed it its own way. */
export type ViewerShareResult = 'shared' | 'copied' | undefined | void;
export type ViewerShare = (request: ViewerShareRequest) => ViewerShareResult | Promise<ViewerShareResult>;

/**
 * The ready-made Share action. `link` turns the request into the URL a person can open to see the same thing. Uses the Web Share
 * API where the browser offers it (phones), otherwise copies the link (see `copyText`) and lets the frame show "Link copied". A cancelled share
 * sheet is not an error.
 */
export function createLinkShare(link: (request: ViewerShareRequest) => string): ViewerShare {
  return async request => {
    const url = link(request);
    const nav = globalThis.navigator;
    if (typeof nav?.share === 'function' && (typeof nav.canShare !== 'function' || nav.canShare({ title: request.title, url }))) {
      try { await nav.share({ title: request.title, url }); return 'shared'; }
      catch (error) { if ((error as { name?: string })?.name === 'AbortError') return undefined; /* fall back to the clipboard */ }
    }
    // Clipboard API, then execCommand; when neither works copyText throws ManualCopyError and the frame shows the link selected.
    await copyText(url);
    return 'copied';
  };
}

